choose.when:
UPDATE inventory_source_offline SET available_stock_count = available_stock_count - #{decreaseQty},
    row_version = row_version + 1, record_hash = #{sourceHashAfter}, updated_at = SYSTIMESTAMP
 WHERE source_record_key = #{sourceRecordKey} AND available_stock_count >= #{decreaseQty}

UPDATE inventory_source_ecommerce SET sellable_quantity = sellable_quantity - #{decreaseQty},
    row_version = row_version + 1, record_hash = #{sourceHashAfter}, updated_at = SYSTIMESTAMP
 WHERE source_record_key = #{sourceRecordKey} AND sellable_quantity >= #{decreaseQty}

UPDATE inventory_source_greeting SET saleable_meal_count = saleable_meal_count - #{decreaseQty},
    row_version = row_version + 1, record_hash = #{sourceHashAfter}, updated_at = SYSTIMESTAMP
 WHERE source_record_key = #{sourceRecordKey} AND saleable_meal_count >= #{decreaseQty}

choose.otherwise:
UPDATE inventory_source_warehouse SET physical_available_qty = physical_available_qty - #{decreaseQty},
    row_version = row_version + 1, record_hash = #{sourceHashAfter}, updated_at = SYSTIMESTAMP
 WHERE source_record_key = #{sourceRecordKey} AND physical_available_qty >= #{decreaseQty}

mapper.insert:
INSERT INTO inventory_demo_adjustment (
    request_id, request_hash, source_type, source_record_key, decrease_qty,
    source_row_version_before, source_row_version_after, source_hash_before, source_hash_after,
    adjustment_status, requested_by, requested_at, applied_at, payload_json
) VALUES (
    #{requestId}, #{requestHash}, #{sourceType}, #{sourceRecordKey}, #{decreaseQty},
    #{sourceRowVersionBefore}, #{sourceRowVersionAfter}, #{sourceHashBefore}, #{sourceHashAfter},
    'APPLIED', #{requestedBy}, SYSTIMESTAMP, SYSTIMESTAMP, #{payloadJson}
)
